class Solution:
    def minMoves(self, balance):
        if sum(balance) < 0:
            return -1
        q = [0]
        for x in balance[1:]:
            q.append(q[-1] + x)
        return min(sum(abs(v + c) for v in q) for c in set(-v for v in q))

