class Solution {
public:
    long long minMoves(vector<int>& balance) {
        long long total = accumulate(balance.begin(), balance.end(), 0LL);
        if (total < 0) return -1;
        int n = balance.size();
        vector<long long> q(n);
        for (int i = 1; i < n; i++) q[i] = q[i-1] + balance[i];
        long long best = LLONG_MAX;
        for (int i = 0; i < n; i++) {
            long long cur = 0;
            for (int j = 0; j < n; j++) cur += llabs(q[j] - q[i]);
            best = min(best, cur);
        }
        return best;
    }
};

