import java.util.Arrays;
class Solution {
    public long minMoves(int[] balance) {
        long total = 0;
        for (int x : balance) total += x;
        if (total < 0) return -1;
        int n = balance.length;
        long[] q = new long[n];
        for (int i = 1; i < n; i++) q[i] = q[i-1] + balance[i];
        Arrays.sort(q);
        long m = q[n / 2], ans = 0;
        for (long v : q) ans += Math.abs(v - m);
        return ans;
    }
}

